+  ld(R0, oopDesc::mark_offset_in_bytes(), object);
+  andi(R0, R0, markWord::inline_type_pattern_mask);
+  cmpwi(CR0, R0, markWord::inline_type_pattern);
+  bne(CR0, not_inline_type);
+}
